// =====================================================
// 🛡️ FILTRO DE SEGURIDAD - SOLO GRUPO DE COMANDO
// =====================================================
// ID del grupo privado de comando
const ID_GRUPO_COMANDO = '120363041361026474@g.us';

// Extraer datos del webhook de YCloud
const body = $input.item.json.body;
const whatsappMsg = body.whatsappInboundMessage;

// Si no es un mensaje de WhatsApp válido, ignorar
if (!whatsappMsg || !whatsappMsg.from) {
    return null;
}

// Obtener el ID del chat (grupo o individual)
const from = whatsappMsg.from || '';
const to = whatsappMsg.to || '';
const messageType = whatsappMsg.type || 'unknown';

// Solo aceptar mensajes de texto
if (messageType !== 'text') {
    console.log('Mensaje no es texto, ignorando');
    return null;
}

// Verificar si el mensaje viene del grupo de comando
// YCloud envía el from como número de teléfono, no como ID de grupo
// Para grupos, necesitamos verificar si hay un context.from que sea el grupo
const context = whatsappMsg.context || {};
const groupId = context.from || '';

// Log para debug
console.log('From:', from);
console.log('Context:', JSON.stringify(context));
console.log('GroupId:', groupId);

// Extraer el texto del comando
const messageText = whatsappMsg.text?.body || '';

// Saludo según hora (COLOMBIA UTC-5)
const now = new Date();
const horaCol = new Date(now.getTime() - 5 * 60 * 60 * 1000).getHours();
let saludo;
if (horaCol < 12) saludo = 'Buenos días';
else if (horaCol < 19) saludo = 'Buenas tardes';
else saludo = 'Buenas noches';

// Pasar el mensaje para procesamiento
return {
    json: {
        mensajeClienteActual: messageText,
        prompt: messageText,
        from: from.replace('+', ''),
        to: to.replace('+', ''),
        saludo: saludo,
        timestamp: whatsappMsg.sendTime,
        customerName: whatsappMsg.customerProfile?.name || 'Director'
    }
};

// ============================================
// EXTRACTOR INTELIGENTE v2.0
// Extrae teléfono y nombre del comando
// ============================================
const prompt = $input.item.json.prompt ||
               $input.item.json.mensajeClienteActual || '';

console.log('Prompt recibido:', prompt);

// ============================================
// 1. EXTRACCIÓN DE TELÉFONO (Formato Colombiano)
// ============================================
const normalizedPrompt = prompt.replace(/[^\d]/g, '');
const phoneRegex = /(?:57)?(3\d{9})/g;
const phoneMatches = normalizedPrompt.match(phoneRegex);
let telefono_objetivo = null;

if (phoneMatches && phoneMatches.length > 0) {
    telefono_objetivo = phoneMatches[0].replace(/^57/, '');
    console.log('Teléfono extraído:', telefono_objetivo);
} else {
    console.log('No se encontró teléfono válido');
}

// ============================================
// 2. EXTRACCIÓN DE NOMBRE
// ============================================
let nombre_extraido = null;
const patrones = [
    /(?:a|al nombre)\s+["']?([A-Za-zÁ-ÿ\s]+?)["']?(?:\s|$)/i,
    /(?:nombre es|llama)\s+["']?([A-Za-zÁ-ÿ\s]+?)["']?(?:\s+y|\s*$)/i,
    /registra(?:\s+el)?\s+nombre\s+["']?([A-Za-zÁ-ÿ\s]+?)["']?(?:\s+para|$)/i,
];

for (const patron of patrones) {
    const match = prompt.match(patron);
    if (match && match[1]) {
        nombre_extraido = match[1].trim();
        const palabrasExcluir = ['del', 'cliente', 'el', 'la', 'un', 'una', 'para', 'de'];
        let palabrasNombre = nombre_extraido.split(/\s+/).filter(palabra => 
            !palabrasExcluir.includes(palabra.toLowerCase())
        );
        nombre_extraido = palabrasNombre.join(' ').trim();
        if (nombre_extraido.length >= 2 && !/^\d+$/.test(nombre_extraido)) {
            console.log('Nombre extraído:', nombre_extraido);
            break;
        } else {
            nombre_extraido = null;
        }
    }
}

// ============================================
// 3. SALIDA ESTRUCTURADA
// ============================================
$input.item.json.telefono_objetivo = telefono_objetivo;
$input.item.json.nombre_extraido = nombre_extraido;

return [$input.item];

